     1	package br.com.loja.pedidos.shipping;
     2	
     3	import java.math.BigDecimal;
     4	import java.net.URI;
     5	import java.net.URLEncoder;
     6	import java.net.http.HttpClient;
     7	import java.net.http.HttpRequest;
     8	import java.net.http.HttpResponse;
     9	import java.nio.charset.StandardCharsets;
    10	import java.time.Duration;
    11	import java.util.Map;
    12	import java.util.concurrent.CompletableFuture;
    13	import java.util.concurrent.TimeUnit;
    14	import org.slf4j.Logger;
    15	import org.slf4j.LoggerFactory;
    16	import org.springframework.beans.factory.annotation.Value;
    17	import org.springframework.stereotype.Component;
    18	import tools.jackson.databind.json.JsonMapper;
    19	
    20	@Component
    21	public class TranslogClient implements CarrierGateway {
    22	
    23	    private static final Logger log = LoggerFactory.getLogger(TranslogClient.class);
    24	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
    25	
    26	    private final String baseUrl;
    27	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
    28	    private final JsonMapper mapper = JsonMapper.builder().build();
    29	
    30	    public TranslogClient(@Value("${translog.url:}") String baseUrl) {
    31	        String url = baseUrl == null ? "" : baseUrl.trim();
    32	        this.baseUrl = url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
    33	    }
    34	
    35	    @Override
    36	    public CarrierResult quote(String zipCode, long weightGrams, ServiceLevel level) {
    37	        if (baseUrl.isEmpty()) {
    38	            log.warn("TRANSLOG_URL is not set");
    39	            return new Unavailable();
    40	        }
    41	        CompletableFuture<HttpResponse<String>> pending = null;
    42	        try {
    43	            String service = level == ServiceLevel.EXPRESS ? "EXP" : "STD";
    44	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
    45	                    + "&weight_g=" + weightGrams + "&service=" + service);
    46	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
    47	            pending = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    48	            HttpResponse<String> response = pending.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
    49	            if (response.statusCode() != 200) {
    50	                return new Unavailable();
    51	            }
    52	            return parse(response.body());
    53	        } catch (InterruptedException e) {
    54	            Thread.currentThread().interrupt();
    55	            return new Unavailable();
    56	        } catch (RuntimeException | java.util.concurrent.ExecutionException
    57	                | java.util.concurrent.TimeoutException e) {
    58	            log.warn("TransLog quote failed: {}", e.toString());
    59	            return new Unavailable();
    60	        } finally {
    61	            if (pending != null && !pending.isDone()) {
    62	                pending.cancel(true);
    63	            }
    64	        }
    65	    }
    66	
    67	    private CarrierResult parse(String body) {
    68	        Map<?, ?> json = mapper.readValue(body, Map.class);
    69	        Object error = json.get("error");
    70	        if (error != null) {
    71	            return "ZIP_NOT_SERVED".equals(error) ? new NotServed() : new Unavailable();
    72	        }
    73	        if (json.get("price_cents") instanceof Number cents && json.get("eta_hours") instanceof Number eta
    74	                && isIntegral(cents) && isIntegral(eta) && cents.longValue() >= 0 && eta.longValue() >= 0) {
    75	            return new Quoted(BigDecimal.valueOf(cents.longValue(), 2), eta.longValue());
    76	        }
    77	        return new Unavailable();
    78	    }
    79	
    80	    private static boolean isIntegral(Number n) {
    81	        return n instanceof Integer || n instanceof Long || n instanceof Short || n instanceof Byte;
    82	    }
    83	}
