    25	/** Computes the purchase summary. Used both for the preview and for registering an order. */
    26	@Service
    27	public class CheckoutService {
    28	
    29	    private static final Pattern ZIP_CODE = Pattern.compile("[0-9]{8}");
    30	    private static final BigDecimal COUPON_CAP = new BigDecimal("0.30");
    31	
    32	    private final ProductRepository products;
    33	    private final Map<String, ShippingOption> shippingOptions = new HashMap<>();
    34	    private final Map<String, Coupon> coupons = new HashMap<>();
    35	    private final Map<String, PaymentMethod> paymentMethods = new HashMap<>();
    36	
    37	    public CheckoutService(ProductRepository products, List<ShippingOption> shippingOptions, List<Coupon> coupons,
    38	                           List<PaymentMethod> paymentMethods) {
    39	        this.products = products;
    40	        shippingOptions.forEach(o -> this.shippingOptions.put(o.code(), o));
    41	        coupons.forEach(c -> this.coupons.put(c.code(), c));
    42	        paymentMethods.forEach(p -> this.paymentMethods.put(p.code(), p));
    43	    }
    44	
    45	    public OrderSummary summarize(CheckoutRequest request) {
    46	        List<PricedItem> items = priceItems(request);
    47	
    48	        ClubTier tier = ClubTier.parse(request.clubTier()).orElseThrow(() -> invalid("INVALID_CLUB_TIER"));
    49	        Region region = Region.parse(request.region()).orElseThrow(() -> invalid("INVALID_REGION"));
    50	        if (request.zipCode() == null || !ZIP_CODE.matcher(request.zipCode()).matches()) {
    51	            throw invalid("INVALID_ZIP_CODE");
    52	        }
    53	        ShippingOption shipping = shippingOptions.get(request.shippingMethod());
    54	        if (shipping == null) {
    55	            throw invalid("INVALID_SHIPPING_METHOD");
    56	        }
    57	
    58	        BigDecimal subtotal = Money.round(items.stream().map(PricedItem::total).reduce(BigDecimal.ZERO, BigDecimal::add));
    59	        BigDecimal weight = items.stream().map(i -> i.weightKg().multiply(BigDecimal.valueOf(i.quantity())))
    60	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    61	        ShippingQuote quote = shipping.quote(new ShippingRequest(request.zipCode(), weight, region));
    62	        BigDecimal shippingCost = tier.freeShipping() && shipping.clubFreeShippingApplies() ? Money.ZERO : quote.cost();
    63	
    64	        BigDecimal couponDiscount = Money.ZERO;
    65	        if (request.couponInformed()) {
    66	            Coupon coupon = coupons.get(request.coupon());
    67	            if (coupon == null) {
    68	                throw invalid("INVALID_COUPON");
    69	            }
    70	            CouponContext context = new CouponContext(request.cpf(), items, subtotal, request.shippingMethod(),
    71	                    shippingCost);
    72	            if (!coupon.applicable(context)) {
    73	                throw invalid("COUPON_NOT_APPLICABLE");
    74	            }
    75	            couponDiscount = Money.round(coupon.discount(context).min(Money.percent(subtotal, COUPON_CAP)));
    76	        }
    77	
    78	        BigDecimal insurance = region.insurance(subtotal);
    79	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
    80	
    81	        PaymentMethod payment = paymentMethods.get(request.paymentMethod());
    82	        if (payment == null) {
    83	            throw invalid("INVALID_PAYMENT_METHOD");
    84	        }
    85	        if (!payment.allowsInstallments(request.installments())) {
    86	            throw invalid("INVALID_INSTALLMENTS");
    87	        }
    88	        if (!payment.availableFor(orderTotal)) {
    89	            throw invalid("PAYMENT_METHOD_UNAVAILABLE");
    90	        }
    91	        PaymentCharge charge = payment.charge(orderTotal, request.installments(), request.couponInformed());
    92	
    93	        return new OrderSummary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
    94	                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), request.installments(),
    95	                charge.installmentAmount(), tier.nextPurchaseCredit(subtotal), tier.gift(subtotal));
    96	    }
    97	
    98	    /** Validates the cart (errors 1 to 4) and prices it with the current catalog. */
    99	    private List<PricedItem> priceItems(CheckoutRequest request) {
   100	        List<CheckoutRequest.Item> cart = request.items();
   101	        if (isBlank(request.cpf()) || isBlank(request.email()) || cart == null || cart.isEmpty()) {
   102	            throw invalid("INVALID_ORDER");
   103	        }
   104	        Set<String> skus = new HashSet<>();
   105	        for (CheckoutRequest.Item item : cart) {
   106	            if (isBlank(item.sku()) || item.quantity() == null || item.quantity() <= 0 || !skus.add(item.sku())) {
   107	                throw invalid("INVALID_ORDER");
   108	            }
   109	        }
   110	        Map<String, Product> catalog = products.findAll(skus).stream()
   111	                .collect(java.util.stream.Collectors.toMap(Product::sku, Function.identity()));
   112	        if (cart.stream().anyMatch(i -> !catalog.containsKey(i.sku()))) {
   113	            throw invalid("UNKNOWN_PRODUCT");
   114	        }
   115	        if (cart.stream().anyMatch(i -> catalog.get(i.sku()).discontinued())) {
   116	            throw invalid("PRODUCT_DISCONTINUED");
   117	        }
   118	        if (cart.stream().anyMatch(i -> catalog.get(i.sku()).stock() < i.quantity())) {
   119	            throw invalid("INSUFFICIENT_STOCK");
   120	        }
   121	        return cart.stream().map(i -> {
   122	            Product p = catalog.get(i.sku());
   123	            return new PricedItem(p.sku(), p.price(), p.weightKg(), i.quantity());
   124	        }).toList();
   125	    }
   126	
   127	    private static boolean isBlank(String value) {
   128	        return value == null || value.isBlank();
   129	    }
