190	    23	    private static final Logger log = LoggerFactory.getLogger(TranslogClient.class);
191	    24	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
192	    25	
193	    26	    private final String baseUrl;
194	    27	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
195	    28	    private final JsonMapper mapper = JsonMapper.builder().build();
196	    29	
197	    30	    public TranslogClient(@Value("${translog.url:}") String baseUrl) {
198	    31	        String url = baseUrl == null ? "" : baseUrl.trim();
199	    32	        this.baseUrl = url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
200	    33	    }
201	    34	
202	    35	    @Override
203	    36	    public CarrierResult quote(String zipCode, long weightGrams, ServiceLevel level) {
204	    37	        if (baseUrl.isEmpty()) {
205	    38	            log.warn("TRANSLOG_URL is not set");
206	    39	            return new Unavailable();
207	    40	        }
208	    41	        CompletableFuture<HttpResponse<String>> pending = null;
209	    42	        try {
210	    43	            String service = level == ServiceLevel.EXPRESS ? "EXP" : "STD";
211	    44	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
212	    45	                    + "&weight_g=" + weightGrams + "&service=" + service);
213	    46	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
214	    47	            pending = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
215	    48	            HttpResponse<String> response = pending.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
216	    49	            if (response.statusCode() != 200) {
217	    50	                return new Unavailable();
218	    51	            }
219	    52	            return parse(response.body());
220	    53	        } catch (InterruptedException e) {
221	    54	            Thread.currentThread().interrupt();
222	    55	            return new Unavailable();
223	    56	        } catch (RuntimeException | java.util.concurrent.ExecutionException
224	    57	                | java.util.concurrent.TimeoutException e) {
225	    58	            log.warn("TransLog quote failed: {}", e.toString());
226	    59	            return new Unavailable();
227	    60	        } finally {
228	    61	            if (pending != null && !pending.isDone()) {
229	    62	                pending.cancel(true);
230	    63	            }
231	    64	        }
232	    65	    }
233	    66	
234	    67	    private CarrierResult parse(String body) {
235	    68	        Map<?, ?> json = mapper.readValue(body, Map.class);
236	    69	        Object error = json.get("error");
237	    70	        if (error != null) {
238	    71	            return "ZIP_NOT_SERVED".equals(error) ? new NotServed() : new Unavailable();
239	    72	        }
240	    73	        if (json.get("price_cents") instanceof Number cents && json.get("eta_hours") instanceof Number eta
241	    74	                && isIntegral(cents) && isIntegral(eta) && cents.longValue() >= 0 && eta.longValue() >= 0) {
242	    75	            return new Quoted(BigDecimal.valueOf(cents.longValue(), 2), eta.longValue());
243	    76	        }
244	    77	        return new Unavailable();
245	    78	    }
246	    79	
247	    80	    private static boolean isIntegral(Number n) {
248	    81	        return n instanceof Integer || n instanceof Long || n instanceof Short || n instanceof Byte;
249	    82	    }
250	    83	}
