    46	        if (m.get("quantity") instanceof Integer i) {
    47	            quantity = i;
    48	        } else if (m.get("quantity") instanceof Long l && l >= Integer.MIN_VALUE && l <= Integer.MAX_VALUE) {
    49	            quantity = l.intValue();
    50	        }
    51	        return new Item(text(m.get("sku")), quantity);
